INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (167, 1, '빌드 컨텍스트', '`docker build -t myapp .` 에서 마지막의 `.` 은 무엇을 뜻할까요? 그리고 Dockerfile 의 `COPY` 는 어디의 파일을 복사할 수 있을까요?', '빌드할 때 도커에 보내는 폴더예요.', NULL, NULL, '[]', 'choice', '["`.` 은 이미지 이름이고 `COPY` 는 컴퓨터의 아무 파일이나 복사할 수 있다", "`.` 은 태그이고 `COPY` 는 컨테이너 안의 파일만 복사할 수 있다", "`.` 은 빌드 컨텍스트(현재 폴더)이고, `COPY` 는 그 컨텍스트 안의 파일만 복사할 수 있다 (컨텍스트에 없는 파일은 `not found` 오류가 난다)", "`.` 은 아무 뜻이 없고 생략해도 된다"]', 2, '`COPY nosuch.txt /x` 처럼 없는 파일을 복사하면 `"/nosuch.txt": not found` 로 빌드가 멈춥니다. 컨텍스트 밖의 파일은 쓸 수 없어요.', NULL, NULL, NULL, NULL),
  (167, 2, '레이어는 언제 생길까', 'Dockerfile 의 줄 중에서 이미지에 크기를 가진 레이어를 만드는 것은 주로 무엇일까요?', '파일을 바꾸는 줄이에요.', NULL, NULL, '[]', 'choice', '["모든 줄이 같은 크기의 레이어를 만든다", "`RUN`, `COPY`, `ADD` 처럼 파일 시스템을 바꾸는 줄이다 (`ENV`, `CMD` 는 크기가 0B 인 설정 기록이다)", "`FROM` 줄만 레이어를 만든다", "`CMD` 줄이 가장 큰 레이어를 만든다"]', 1, '`docker history 이미지` 로 줄마다 크기를 볼 수 있습니다. `ENV MODE=prod` 는 `0B`, `COPY` 와 `RUN` 은 파일이 들어간 크기로 나와요.', NULL, NULL, NULL, NULL),
  (167, 3, '같은 빌드를 다시 하면', 'Dockerfile 과 복사하는 파일을 하나도 바꾸지 않고 `docker build` 를 한 번 더 실행하면 어떻게 될까요?', '이미 만든 결과를 재사용해요.', NULL, NULL, '[]', 'choice', '["각 단계가 `CACHED` 로 표시되며 캐시를 재사용해 거의 즉시 끝난다", "처음부터 모든 단계를 다시 실행한다", "같은 이름의 이미지가 이미 있다는 오류가 난다", "이미지가 삭제된다"]', 0, '도커는 줄의 내용과 복사한 파일이 같으면 이전 결과를 재사용합니다. 빌드 로그의 `CACHED` 가 그 표시예요.', NULL, NULL, NULL, NULL),
  (167, 4, '캐시는 한 번 깨지면 뒤까지', '`FROM`, `COPY deps.txt .`, `RUN` 설치, `COPY src/ src/` 순서로 된 Dockerfile 에서 `deps.txt` 를 바꾸고 다시 빌드했습니다. 어떻게 될까요?', '바뀐 줄부터는 캐시를 쓸 수 없어요.', NULL, NULL, '[]', 'choice', '["바뀐 `COPY deps.txt` 한 줄만 다시 실행된다", "모든 단계가 다시 실행되지만 `FROM` 은 제외된다", "아무것도 다시 실행되지 않는다", "`deps.txt` 를 복사하는 줄과 그 뒤의 `RUN`, `COPY src/` 가 모두 다시 실행된다 (바뀐 줄 앞의 단계는 캐시를 쓴다)"]', 3, '한 단계의 캐시가 깨지면 그 뒤의 단계는 모두 새로 만들어집니다. 반대로 `src/` 만 바꾸면 `COPY src/` 한 단계만 다시 실행돼요.', NULL, NULL, NULL, NULL),
  (167, 5, '자주 바뀌는 파일은 뒤에', '빌드를 빠르게 하려면 `COPY` 줄의 순서는 어떻게 하는 것이 좋을까요?', '캐시가 깨지는 줄을 뒤로 보내요.', NULL, NULL, '[]', 'choice', '["자주 바뀌는 소스를 가장 먼저 복사한다", "순서는 캐시에 영향이 없다", "잘 바뀌지 않는 파일(의존성 목록)을 먼저 복사해 설치하고, 자주 바뀌는 소스는 나중에 복사한다", "모든 파일을 한 번에 복사한 뒤 설치한다"]', 2, '소스만 고쳤을 때 설치 단계가 캐시로 건너뛰어집니다. 설치가 오래 걸리는 프로젝트일수록 효과가 커요.', NULL, NULL, NULL, NULL),
  (167, 6, '--no-cache', '`docker build --no-cache` 는 무엇을 할까요?', '이전 결과를 믿지 않아요.', NULL, NULL, '[]', 'choice', '["이미지를 저장하지 않는다", "캐시를 쓰지 않고 `RUN` 같은 모든 단계를 처음부터 다시 실행한다", "빌드 로그를 숨긴다", "컨테이너를 삭제한다"]', 1, '`RUN` 이 무작위 값을 만들면 캐시를 쓸 때는 값이 그대로이고, `--no-cache` 로 빌드하면 새 값이 나옵니다. 캐시 때문에 안 바뀐다고 의심될 때 써요.', NULL, NULL, NULL, NULL),
  (167, 7, '.dockerignore 의 역할', '빌드 폴더에 `.dockerignore` 파일이 있고 `secret.env` 가 적혀 있습니다. `COPY . /app` 으로 빌드하면 어떻게 될까요?', '컨텍스트에서 빠져요.', NULL, NULL, '[]', 'choice', '["`secret.env` 는 빌드 컨텍스트에서 제외되어 이미지 안에 들어가지 않는다", "`secret.env` 가 이미지에 그대로 들어간다", "빌드가 오류로 멈춘다", "`secret.env` 파일이 폴더에서 삭제된다"]', 0, '.dockerignore 가 없으면 `COPY . .` 가 비밀 값이 든 파일도 이미지에 넣습니다. 이미지를 공유하기 전에 꼭 확인하세요.', NULL, NULL, NULL, NULL),
  (167, 8, '제외한 파일을 COPY 하면', '`.dockerignore` 에 `secret.env` 를 적어 놓고 Dockerfile 에서 `COPY secret.env /s.env` 를 썼습니다. 빌드는 어떻게 될까요?', '컨텍스트에 없는 파일이에요.', NULL, NULL, '[]', 'choice', '["파일이 정상적으로 복사된다", "경고만 나오고 빈 파일이 복사된다", "빌드가 성공하고 파일이 이미지에서 숨겨진다", "컨텍스트에서 제외되었으므로 `\\"/secret.env\\": not found` 오류로 빌드가 멈춘다"]', 3, '파일이 폴더에 분명히 있는데 not found 가 나오면 `.dockerignore` 를 먼저 의심하세요.', NULL, NULL, NULL, NULL),
  (167, 9, '! 로 예외 두기', '`.dockerignore` 에 `*.log` 와 `!keep.log` 를 순서대로 적었습니다. `debug.log` 와 `keep.log` 중 이미지에 들어가는 것은?', '`!` 는 제외에서 다시 뺀다는 뜻이에요.', NULL, NULL, '[]', 'choice', '["둘 다 들어간다", "둘 다 들어가지 않는다", "`keep.log` 만 들어간다 (`*.log` 로 로그를 모두 제외하고 `!keep.log` 로 그 파일만 다시 포함한다)", "`debug.log` 만 들어간다"]', 2, '예외는 제외 줄보다 뒤에 적어야 합니다. `!keep.log` 를 `*.log` 앞에 쓰면 `keep.log` 도 제외돼요.', NULL, NULL, NULL, NULL),
  (167, 10, '컨텍스트가 크면', '`COPY . /app` 으로 빌드하는 폴더에 20MB 짜리 큰 파일이 있습니다. 그 파일을 `.dockerignore` 에 넣으면 빌드 로그의 `transferring context` 는 어떻게 달라질까요?', '도커에 보내는 양이에요.', NULL, NULL, '[]', 'choice', '["달라지지 않는다", "컨텍스트 전송량이 약 21MB 에서 100바이트 정도로 줄어 빌드가 빨라진다", "오히려 늘어난다", "빌드가 실패한다"]', 1, 'node_modules, .git, 빌드 결과물 같은 큰 폴더를 제외하면 빌드 시작이 빨라지고 이미지도 작아집니다.', NULL, NULL, NULL, NULL),
  (167, 11, '나중에 지워도 이미지는 안 줄어든다', '한 줄에서 10MB 파일을 만들고(`RUN dd ...`) 그다음 줄에서 `RUN rm /big` 으로 지웠습니다. 이미지의 크기는 어떨까요?', '앞 레이어는 그대로 남아요.', NULL, NULL, '[]', 'choice', '["10MB 파일을 만든 레이어가 그대로 남아 있어서 이미지 크기는 줄지 않는다 (`rm` 레이어는 4kB 정도만 추가된다)", "10MB 가 줄어든 작은 이미지가 된다", "빌드가 오류로 멈춘다", "파일이 이미지 밖으로 이동한다"]', 0, '레이어는 쌓이기만 하고 앞의 레이어는 바뀌지 않습니다. 파일이 보이지 않아도 크기는 남아 있어요.', NULL, NULL, NULL, NULL),
  (167, 12, '한 RUN 으로 합치기', '10MB 임시 파일을 만들고 지우는 작업을 이미지 크기를 늘리지 않으려면 어떻게 써야 할까요?', '만들고 지우는 일이 같은 레이어 안에서 끝나야 해요.', NULL, NULL, '[]', 'choice', '["`RUN` 두 줄로 나눠 쓴다", "`CMD` 에서 지운다", "`ENV` 로 파일 경로를 적는다", "한 줄의 `RUN` 에서 `&&` 로 이어 만들고 바로 지운다 (`RUN dd ... && rm /big`)"]', 3, '같은 레이어 안에서 만들고 지우면 파일이 레이어에 남지 않습니다. 패키지 설치 뒤 캐시 정리도 같은 방식으로 해요.', NULL, NULL, NULL, NULL),
  (167, 13, 'ARG 와 ENV', '`ARG VER=1` 과 `ENV MODE=prod` 를 Dockerfile 에 썼습니다. `docker build --build-arg VER=9` 로 빌드한 이미지로 컨테이너를 실행하면 두 값은 어떻게 보일까요?', '하나는 빌드 중에만 있어요.', NULL, NULL, '[]', 'choice', '["둘 다 컨테이너 안에 항상 남는다", "둘 다 빌드가 끝나면 사라진다", "`ARG` 인 `VER` 는 빌드 중에만 쓰이고 실행한 컨테이너 환경에는 없으며, `ENV` 인 `MODE` 는 실행할 때도 남아 `docker run -e` 로 덮어쓸 수 있다", "`ARG` 만 컨테이너 안에 남는다"]', 2, '빌드 중에 `RUN echo $VER` 로 쓴 값(여기서는 9)은 결과 파일에 남지만, 컨테이너의 환경 변수 `VER` 는 없습니다.', NULL, NULL, NULL, NULL),
  (167, 14, 'docker tag 는 복사일까', '`docker tag myapp:4 myapp:alias` 를 실행하면 이미지는 어떻게 될까요?', '이름표를 하나 더 붙여요.', NULL, NULL, '[]', 'choice', '["이미지가 복사되어 용량이 두 배가 된다", "이미지를 복사하지 않고 같은 이미지(같은 ID)에 이름을 하나 더 붙인다", "기존 이름이 사라진다", "컨테이너가 하나 만들어진다"]', 1, '`docker image inspect` 의 ID 가 두 이름에서 같습니다.', NULL, NULL, NULL, NULL),
  (167, 15, '이미지 빌드', '현재 폴더를 빌드 컨텍스트로 해서 `myapp:1` 이미지를 만드는 명령의 마지막 인자를 채우세요.', '현재 폴더를 뜻하는 한 글자예요.', NULL, NULL, '[]', 'fill', '[".", "*", "./Dockerfile", "-"]', NULL, '마지막 인자는 컨텍스트 폴더입니다. Dockerfile 이름이 아니에요.', '[0]', 'docker build -t myapp:1 {0}', NULL, NULL),
  (167, 16, '캐시 무시', '캐시를 쓰지 않고 처음부터 빌드하는 옵션을 채우세요.', '"캐시 없음"을 뜻해요.', NULL, NULL, '[]', 'fill', '["--no-cache", "--clean", "--fresh", "--cache=off"]', NULL, '`RUN` 이 외부 상태에 의존할 때 최신 결과가 필요하면 이 옵션을 씁니다.', '[0]', 'docker build {0} -t myapp .', NULL, NULL),
  (167, 17, '레이어 크기 보기', '이미지의 **줄별 크기**를 보여 주는 하위 명령을 채우세요.', '"이력"이라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["history", "layers", "inspect", "size"]', NULL, '큰 레이어가 어느 줄에서 생겼는지 찾을 때 씁니다.', '[0]', 'docker {0} myapp:1', NULL, NULL),
  (167, 18, '제외 목록 파일', '빌드 컨텍스트에서 제외할 파일 목록을 적는 **파일 이름**을 채우세요.', '점으로 시작하고 "docker"와 "ignore"가 이어져요.', NULL, NULL, '[]', 'fill', '[".dockerignore", ".gitignore", ".dockerexclude", "dockerignore.txt"]', NULL, '`.gitignore` 는 Git 용이라서 도커 빌드에는 쓰이지 않습니다. 컨텍스트 폴더의 맨 위에 둬요.', '[0]', 'cat {0}', NULL, NULL),
  (167, 19, '예외로 다시 포함', '`*.log` 로 제외했지만 `keep.log` 만은 **다시 포함**하는 줄의 파일 이름을 채우세요.', '느낌표 뒤에 파일 이름을 적어요.', NULL, NULL, '[]', 'fill', '["keep.log", "*.log", "keep", "~keep.log"]', NULL, '`!` 줄은 앞의 제외 줄 뒤에 적어야 합니다.', '[0]', '!{0}', NULL, NULL),
  (167, 20, '빌드 인자 넘기기', 'Dockerfile 의 `ARG VER` 에 값 9 를 넘기는 옵션 이름을 채우세요.', '"빌드 인자"라는 뜻이에요.', NULL, NULL, '[]', 'fill', '["build-arg", "arg", "env", "set"]', NULL, '`ENV` 값은 `docker run -e` 로 넘기고, `ARG` 값은 `--build-arg` 로 넘깁니다.', '[0]', 'docker build --{0} VER=9 .', NULL, NULL),
  (167, 21, 'Dockerfile 이름 지정', '이름이 `Dockerfile.dev` 인 파일로 빌드하려고 합니다. 옵션을 채우세요.', '"파일"을 뜻하는 한 글자 옵션이에요.', NULL, NULL, '[]', 'fill', '["-f", "-d", "-p", "-c"]', NULL, '`-f` 를 생략하면 컨텍스트 폴더의 `Dockerfile` 을 찾습니다.', '[0]', 'docker build {0} Dockerfile.dev -t dev .', NULL, NULL),
  (167, 22, '이름 하나 더 붙이기', '`myapp:1` 이미지에 `myapp:stable` 이름을 **하나 더 붙이는** 하위 명령을 채우세요.', '"태그"라는 뜻의 영어 단어예요.', NULL, NULL, '[]', 'fill', '["tag", "name", "label", "alias"]', NULL, '이미지를 복사하지 않고 같은 이미지에 이름을 붙입니다.', '[0]', 'docker {0} myapp:1 myapp:stable', NULL, NULL),
  (167, 23, '이미지 삭제', '이미지 `myapp:1` 을 **삭제**하는 하위 명령을 채우세요.', '"이미지 삭제"를 줄인 이름이에요.', NULL, NULL, '[]', 'fill', '["rmi", "rm", "delete", "remove"]', NULL, '`docker rm` 은 컨테이너를 지우는 명령이라 이미지 이름을 주면 `No such container` 오류가 납니다.', '[0]', 'docker {0} myapp:1', NULL, NULL),
  (167, 24, '만들고 바로 지우기', '임시 파일을 만들고 **같은 레이어 안에서** 지우도록 이어 줄 연산자를 채우세요.', '앞이 성공하면 뒤를 실행하는 두 글자예요.', NULL, NULL, '[]', 'fill', '["&&", "||", "|", ">"]', NULL, '`&&` 앞의 명령이 실패하면 뒤는 실행되지 않고 빌드가 멈춥니다.', '[0]', 'RUN dd if=/dev/zero of=/big bs=1M count=10 {0} rm /big', NULL, NULL),
  (167, 25, '이미지 목록', '로컬에 있는 이미지 목록을 보는 명령의 하위 명령을 채우세요.', '"목록"을 뜻하는 두 글자예요.', NULL, NULL, '[]', 'fill', '["ls", "list", "show", "all"]', NULL, '`docker images` 도 같은 목록을 보여 줍니다.', '[0]', 'docker image {0}', NULL, NULL),
  (167, 26, '캐시를 살리는 Dockerfile 순서', '소스를 고쳐도 의존성 설치를 다시 하지 않도록 Dockerfile 을 쓰는 순서입니다. 순서에 맞게 놓아 보세요.', '기반 이미지 → 잘 안 바뀌는 것 → 설치 → 자주 바뀌는 것 순서예요.', NULL, NULL, '[]', 'order', '["`FROM` 으로 기반 이미지를 정한다", "의존성 목록 파일만 먼저 `COPY` 한다", "`RUN` 으로 의존성을 설치한다", "나머지 소스를 `COPY` 한다"]', NULL, '소스만 바뀌면 설치 단계는 `CACHED` 로 건너뛰고 마지막 `COPY` 만 다시 실행됩니다.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (167, 27, '.dockerignore 적용 확인', '.dockerignore 로 불필요한 파일을 빼고 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '제외 목록 작성 → 빌드 → 이미지 안 확인 → 필요한 파일 누락 점검 순서예요.', NULL, NULL, '[]', 'order', '["제외할 파일을 `.dockerignore` 에 적는다", "`docker build -t 이름 .` 으로 빌드한다", "`docker run --rm 이름 ls -A` 로 이미지 안에 어떤 파일이 있는지 본다", "필요한 파일이 빠졌다면(`not found`) `.dockerignore` 의 패턴을 고쳐 다시 빌드한다"]', NULL, '제외 목록이 너무 넓으면 필요한 파일까지 빠집니다. 빌드가 성공해도 이미지 안을 한 번 확인하세요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (167, 28, '큰 이미지의 원인 찾기', '이미지가 예상보다 클 때 원인을 찾아 줄이는 순서입니다. 순서에 맞게 놓아 보세요.', '크기 확인 → 큰 줄 찾기 → 고치기 → 비교 순서예요.', NULL, NULL, '[]', 'order', '["`docker image ls` 로 이미지 크기를 확인한다", "`docker history 이미지` 로 큰 레이어가 생긴 줄을 찾는다", "그 줄을 `&&` 로 합쳐 임시 파일을 같은 레이어에서 지우거나 `.dockerignore` 에 큰 파일을 넣는다", "다시 빌드해 `docker image ls` 의 크기가 줄었는지 비교한다"]', NULL, '나중 줄에서 지우는 것으로는 줄지 않습니다. 파일이 만들어진 레이어를 고쳐야 해요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (167, 29, '캐시 때문에 안 바뀌는지 확인', '빌드 결과가 최신이 아닌 것 같을 때 캐시 영향을 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '빌드 → 같은 빌드로 캐시 확인 → 캐시 없이 빌드 → 결과 비교 순서예요.', NULL, NULL, '[]', 'order', '["`docker build -t 이름:a .` 로 빌드한다", "같은 명령을 다시 실행해 단계가 `CACHED` 로 표시되는지 본다", "`docker build --no-cache -t 이름:b .` 로 캐시 없이 빌드한다", "두 이미지를 실행해 결과가 달라지는지 비교한다"]', NULL, '결과가 달라지면 `RUN` 이 시간이나 외부 상태에 의존하는 것입니다. 그 줄은 캐시를 믿으면 안 돼요.', '[0, 1, 2, 3]', NULL, NULL, NULL);
